INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000001', 'aagri-community-identity', 'ABOUT', 'आगरी समाज: ओळख आणि आजच्या वाटा', 'Aagri identity, and the paths ahead', 'कोकणातील भाषा आणि ऐतिहासिक संदर्भांमधून समाजाची ओळख जाणून घ्या; आजचा समाज अनेक क्षेत्रांत कार्यरत आहे.', 'Discover community identity through language and historical context, while making room for many professions and individual experiences.', 'आगरी ही केवळ व्यवसायाची ओळख नाही; या व्यासपीठावर ती समाजाची ओळख आहे. मराठी विश्वकोशातील आगरी बोलीच्या नोंदीत कोकण पट्ट्यातील भाषिक परंपरेचा संदर्भ मिळतो. जुन्या जिल्हा गॅझेटिअरमध्ये किनारपट्टीवरील वस्ती आणि त्या काळातील उपजीविकांची माहिती आढळते.

इतिहासातील नोंदी आजच्या प्रत्येक व्यक्तीचा व्यवसाय, आहार, प्रथा किंवा जीवनशैली ठरवत नाहीत. हे समुदाय व्यासपीठ सर्व क्षेत्रांतील उद्योजक, विद्यार्थी आणि समाजबांधवांना उपयुक्त माहिती मिळवण्यासाठी खुले आहे.

या संकेतस्थळावरील ऐतिहासिक संस्थात्मक संदर्भ म्हणजे संबंधित संस्थेची आजची अधिकृत मान्यता किंवा संलग्नता नाही. नवीन संस्था, कामगिरी आणि उपक्रमांविषयी माहिती प्रकाशित करण्यासाठी विश्वासार्ह संदर्भ आवश्यक आहेत.', 'Aagri is a community identity, rather than a label for an agriculture-only website. Marathi Vishwakosh documents the community’s speech in the Konkan region, while older district gazetteers provide historical context for coastal settlements and livelihoods.

Historical records do not define every person’s occupation, food, customs or life today. This platform welcomes entrepreneurs, students and community members across professions.

References to institutions in historical material do not establish this website’s current official affiliation. New organizational information, achievements and initiatives need supporting evidence before publication.', '[{"label":"Marathi Vishwakosh · आगरी बोली · 2026","url":"https://marathivishwakosh.org/75706/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, NULL, '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000002', 'aagri-language-heritage', 'CULTURE', 'आगरी बोली: आपल्या ओळखीचा जिवंत धागा', 'Aagri speech: a living thread of identity', 'मराठी विश्वकोशातील नोंदीच्या आधारे आगरी बोलीची भाषिक वैशिष्ट्ये आणि शेजारी बोलींशी असलेला संबंध जाणून घ्या.', 'Explore Aagri speech through the Marathi Vishwakosh reference on its linguistic features and connections with neighbouring varieties.', 'मराठी विश्वकोशातील २२ जून २०२६ च्या आगरी बोलीविषयक नोंदीनुसार आगरी बोली कोकण पट्ट्यातील आगरी समाजात प्रामुख्याने बोलली जाते. तिच्या ध्वनिव्यवस्थेची आणि व्याकरणाची वैशिष्ट्ये या संदर्भात मांडली आहेत. शेजारच्या कोळी व वाडवळी बोलींशी असलेल्या आदानप्रदानाचाही उल्लेख आहे.

भाषेचे जतन करताना वेगवेगळ्या गावांतील आणि पिढ्यांतील बोलण्यातील विविधतेला स्थान द्यायला हवे. वैयक्तिक अनुभव किंवा आठवणी संपूर्ण समाजाचे सार्वत्रिक वर्णन म्हणून मांडू नयेत.

लोककला, सण, खाद्यपरंपरा किंवा मौखिक इतिहासाविषयी माहिती सुचवताना त्या परंपरेचा स्थानिक संदर्भ, सांगणाऱ्या व्यक्तीची संमती आणि शक्य तिथे प्रकाशित संदर्भ द्या.', 'The Marathi Vishwakosh entry dated 22 June 2026 describes Aagri speech, chiefly associated with the Aagri community in the Konkan belt. It discusses its sound system, grammar and exchanges with neighbouring Koli and Wadvali speech.

Language preservation benefits from recognising variation between places and generations. One person’s recollection should not be presented as a universal description of the community.

To contribute material about art, festivals, food or oral history, include the local context, the contributor’s permission and a published reference where possible.', '[{"label":"Marathi Vishwakosh · Renuka Ozarkar · 22 June 2026","url":"https://marathivishwakosh.org/75706/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, true, NULL, '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000003', 'coastal-livelihoods-historical-record', 'CULTURE', 'मिठागरे, खाड्या आणि भातशेती: ऐतिहासिक नोंदी', 'Salt pans, creeks and rice: historical records', '१८८२–१८८३ च्या ठाणे आणि कुलाबा गॅझेटिअरमधील उपजीविका व भूगोलविषयक निवडक संदर्भ.', 'Selected occupational and geographical references from the Thana and Kolaba Gazetteers of 1882–1883.', '१८८२ च्या ठाणे गॅझेटिअरमध्ये वसई, घोडबंदर, पनवेल आणि उरण परिसरातील आगरी मिठागर कामगारांची नोंद आहे. १८८३ च्या कुलाबा गॅझेटिअरमध्ये अलिबाग व पेणच्या खाडीकिनारी वस्ती, मीठनिर्मिती आणि खारजमिनीतील भातशेतीचा संदर्भ आढळतो.

या नोंदी वसाहतकालीन प्रशासनाने तयार केलेल्या आहेत. त्यांतील पूर्वग्रहदूषित सामाजिक वर्णने, लोककथा किंवा जुनी लोकसंख्या ही आजची तथ्ये म्हणून स्वीकारू नयेत. येथे केवळ मर्यादित भौगोलिक आणि उपजीविकाविषयक संदर्भ दिले आहेत.

या ऐतिहासिक नोंदी आजच्या संपूर्ण समाजाचा व्यवसाय किंवा जीवनशैली ठरवत नाहीत. पुढील वाचनासाठी मूळ सरकारी संग्रहातील संदर्भ पाहा.', 'The 1882 Thana Gazetteer records Aagri salt workers around Bassein, Ghodbandar, Panvel and Uran. The 1883 Kolaba Gazetteer refers to communities along the creeks of Alibag and Pen, including salt making and cultivation of saline rice land.

These are colonial administrative records. Their prejudicial social descriptions, origin folklore and population counts should not be treated as present-day facts. This article uses only bounded geographical and occupational references.

These records do not determine the occupations or lifestyles of the community today. Consult the original government archive for further reading.', '[{"label":"Maharashtra Gazetteers · Thana · 1882","url":"https://www.gazetteers.maharashtra.gov.in/cultural.maharashtra.gov.in/english/gazetteer/Thana%20District/Thane-I/trade_crafts.html"},{"label":"Maharashtra Gazetteers · Kolaba · 1883","url":"https://www.gazetteers.maharashtra.gov.in/cultural.maharashtra.gov.in/english/gazetteer/Kolaba%20District/population_husbandmen.html"}]'::jsonb, 'HISTORICAL', 'PUBLISHED', true, true, NULL, '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000004', 'aagri-economic-development-corporation', 'ORGANIZATION', 'आगरी समाज आर्थिक विकास महामंडळ', 'Aagri Samaj Economic Development Corporation', 'महामंडळाच्या अधिकृत योजनांची माहिती, शासन निर्णय, आवश्यक कागदपत्रे आणि संपर्क तपशीलांसाठी सरकारी संदर्भ.', 'Find official scheme information, government resolutions, document requirements and authority contact details.', '४ मार्च २०२५ च्या शासन निर्णयानुसार आगरी समाज आर्थिक विकास महामंडळ स्थापन करण्यास महाराष्ट्र शासनाने मान्यता दिली. महामंडळाच्या अधिकृत संकेतस्थळावर योजना, शासन निर्णय आणि संपर्क माहिती दिली आहे.

सहाय्याची पात्रता, लागू कागदपत्रे आणि अर्जाची पद्धत संबंधित अधिकृत कार्यालयाकडून निश्चित करा. या संकेतस्थळावर माहिती दिली आहे म्हणून कर्ज, सहाय्य किंवा अर्जाची मंजुरी मिळण्याची हमी नाही.

ही सरकारी माहितीची संदर्भ नोंद आहे. हे महामंडळ या समुदाय संकेतस्थळाचे संचालक, भागीदार किंवा मान्यता देणारी संस्था असल्याचा दावा केला जात नाही.', 'Maharashtra approved the establishment of the Aagri Samaj Economic Development Corporation through a government resolution dated 4 March 2025. Its official website provides scheme information, government resolutions and contact information.

Confirm eligibility, required documents and the application process with the authority. Inclusion here does not guarantee a loan, financial support or application approval.

This is a reference to a government resource. It does not claim that the corporation operates, partners with or endorses this community website.', '[{"label":"Aagri Samaj Economic Development Corporation · Government of Maharashtra","url":"https://asavmu.maharashtra.gov.in/"},{"label":"Government resolution · 4 March 2025","url":"https://gr.maharashtra.gov.in/Site/Upload/Government%20Resolutions/English/202503041251338134.pdf"}]'::jsonb, 'CURRENT', 'PUBLISHED', true, true, 'https://asavmu.maharashtra.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000005', 'mahadbt-scholarships', 'EDUCATION', 'महाडीबीटी: शिष्यवृत्ती व शुल्क सहाय्य', 'MahaDBT: scholarships & fee support', 'महाराष्ट्रातील शिष्यवृत्ती व शुल्क सहाय्य योजना, पात्रता आणि अर्जाची स्थिती यांसाठी अधिकृत पोर्टल.', 'Explore Maharashtra scholarship and fee-support schemes, eligibility guidance and application tracking.', 'नोंदणीपूर्वी योजनेची पात्रता, आवश्यक कागदपत्रे आणि अर्जाची मुदत तपासा. पोर्टलवरील सेवा व देखभाल सूचनांनुसार अर्ज प्रक्रिया उपलब्ध आहे का ते निश्चित करा. येथे तुमचा अर्ज किंवा वैयक्तिक कागदपत्रे गोळा केली जात नाहीत.', 'Before registering, read each scheme’s eligibility, document checklist and application window. Check the portal’s service and maintenance notices for availability. This community website does not collect scholarship applications or personal documents.', '[{"label":"Aaple Sarkar DBT · Government of Maharashtra","url":"https://mahadbt.maharashtra.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, true, 'https://mahadbt.maharashtra.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000006', 'national-scholarship-portal', 'EDUCATION', 'राष्ट्रीय शिष्यवृत्ती पोर्टल', 'National Scholarship Portal', 'भारत सरकारच्या विद्यार्थी पोर्टलवर शिष्यवृत्ती योजना आणि अर्जाच्या अधिकृत सूचना पाहा.', 'Find scholarship schemes and official application guidance on the Government of India student portal.', 'पात्रता, नोंदणी, कागदपत्रे आणि संबंधित योजनेच्या मुदती पोर्टलवर वाचा. प्रत्येक योजना सर्व अर्जदारांसाठी लागू असेलच असे नाही. अर्ज केवळ संबंधित अधिकृत पोर्टलवर करा.', 'Read the portal’s eligibility, registration, document and scheme-specific deadline guidance. Not every scheme applies to every applicant. Submit applications only through the relevant official portal.', '[{"label":"National Scholarship Portal · Government of India","url":"https://scholarships.gov.in/Students"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, 'https://scholarships.gov.in/Students', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000007', 'national-career-service', 'EDUCATION', 'राष्ट्रीय करिअर सेवा: रोजगार व मार्गदर्शन', 'National Career Service: jobs & guidance', 'कामगार व रोजगार मंत्रालयाच्या पोर्टलवर नोकऱ्या, करिअर मार्गदर्शन व रोजगार मेळाव्यांची माहिती शोधा.', 'Search jobs, career guidance and job-fair information through the Ministry of Labour & Employment.', 'NCS नोंदणी, अर्ज आणि मुलाखत प्रक्रियेसाठी शुल्क आकारत नसल्याचे सांगते. नोकरीसाठी पैसे किंवा संवेदनशील कागदपत्रे मागणाऱ्या संदेशांची पडताळणी करा. अर्ज करण्यापूर्वी नियोक्ता आणि पदाचे तपशील वाचा.', 'NCS states that registration, job applications and interview processing are free. Check messages asking for payment or sensitive documents carefully. Review the employer and role details before applying.', '[{"label":"National Career Service · Ministry of Labour & Employment","url":"https://ncs.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, true, 'https://ncs.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000008', 'skill-india-courses', 'EDUCATION', 'स्किल इंडिया डिजिटल हब: कौशल्य अभ्यासक्रम', 'Skill India Digital Hub: skill courses', 'कौशल्य अभ्यासक्रम शोधा आणि अभ्यासक्रमाची पात्रता, शिकवण्याची पद्धत व शुल्क तपासा.', 'Discover skill courses and compare requirements, delivery formats and fees before enrolling.', 'तुमच्या शिक्षणाशी, वेळेशी आणि उद्दिष्टांशी जुळणारा अभ्यासक्रम निवडा. शुल्क, प्रमाणपत्राच्या अटी, कालावधी आणि प्रशिक्षण देणाऱ्या संस्थेचे तपशील संबंधित अभ्यासक्रमात तपासा. सर्व अभ्यासक्रम विनामूल्य किंवा रोजगाराची हमी देणारे आहेत असे गृहित धरू नका.', 'Choose a course that fits your education, schedule and goals. Confirm fees, certification conditions, duration and provider information on the individual listing. Do not assume every course is free or guarantees employment.', '[{"label":"Skill India Digital Hub · official course catalogue","url":"https://courses.skillindiadigital.gov.in/courses/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, 'https://courses.skillindiadigital.gov.in/courses/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000009', 'mahaswayam-careers', 'EDUCATION', 'महास्वयम: कौशल्य, रोजगार व उद्योजकता', 'Mahaswayam: skills, employment & enterprise', 'महाराष्ट्रातील प्रशिक्षण, आयटीआय, रोजगार नोंदणी आणि स्टार्टअप उपक्रमांचे अधिकृत दुवे.', 'Official Maharashtra links to training, ITIs, employment exchange and startup initiatives.', 'तुमच्या गरजेनुसार संबंधित सेवा निवडा आणि तिच्या अद्ययावत अटी व नोंदणी सूचना वाचा. या संदर्भ नोंदीमुळे विशिष्ट प्रशिक्षण, नोकरी किंवा सहाय्य मंजूर झाले आहे असा अर्थ होत नाही.', 'Select the service relevant to your needs and read its current requirements and registration instructions. This reference does not establish admission to a course, employment or approval for assistance.', '[{"label":"Mahaswayam · Government of Maharashtra","url":"https://www.mahaswayam.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, 'https://www.mahaswayam.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000010', 'swayam-online-learning', 'EDUCATION', 'स्वयम्: ऑनलाइन शिक्षण', 'SWAYAM: online learning', 'सहभागी संस्थांचे ऑनलाइन अभ्यासक्रम आणि शिक्षणाचे पर्याय शोधा.', 'Explore online courses and learning options from participating institutions.', 'अभ्यासक्रमाची पूर्वतयारी, शिकण्याचा कालावधी आणि सत्राचे वेळापत्रक तपासा. शिक्षण विनामूल्य असले तरी प्रमाणपत्र, परीक्षा किंवा इतर अटी वेगळ्या असू शकतात. त्या संबंधित अभ्यासक्रमाच्या अधिकृत पानावर वाचा.', 'Check prerequisites, study time and the course session schedule. Free access to learning does not necessarily mean a free certificate or examination. Read the conditions on the official course page.', '[{"label":"SWAYAM · Ministry of Education","url":"https://swayam.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, 'https://swayam.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000011', 'udyam-registration', 'RESOURCE', 'उद्यम नोंदणी: लघु उद्योगांसाठी मार्गदर्शन', 'Udyam registration: guidance for small businesses', 'सूक्ष्म, लघु व मध्यम उद्योग मंत्रालयाच्या अधिकृत नोंदणी सूचना आणि अटी वाचा.', 'Read the Ministry of MSME’s official registration guidance and requirements.', 'अधिकृत पोर्टलनुसार उद्यम नोंदणी विनामूल्य आणि कागदविरहित आहे. योग्य अधिकृत संकेतस्थळ वापरा आणि नोंदणीसाठी लागणाऱ्या अद्ययावत अटी तपासा. या समुदाय पोर्टलवरील व्यवसाय नोंदणी ही सरकारी उद्यम नोंदणीपेक्षा वेगळी आहे.', 'The official portal states that Udyam registration is free and paperless. Use the official website and check current registration requirements. A business listing on this community platform is separate from government Udyam registration.', '[{"label":"Udyam Registration · Ministry of MSME","url":"https://www.udyamregistration.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, true, 'https://www.udyamregistration.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "CommunityContent" ("id", "slug", "kind", "titleMr", "titleEn", "summaryMr", "summaryEn", "bodyMr", "bodyEn", "sources", "period", "status", "sourceVerified", "featured", "actionUrl", "verifiedAt", "updatedAt") VALUES ('00000000-0000-4000-8000-000000000012', 'startup-india-resources', 'RESOURCE', 'स्टार्टअप इंडिया: उद्योजकांसाठी साधने', 'Startup India: resources for founders', 'स्टार्टअप शिक्षणसाधने, मान्यतेचे मार्गदर्शन आणि शासकीय योजनांची माहिती पाहा.', 'Explore startup learning resources, recognition guidance and government scheme information.', 'स्टार्टअप मान्यता आणि सहाय्यासाठी वेगवेगळ्या अटी लागू होतात. तुमच्या व्यवसायाला लागू होणारी पात्रता आणि आवश्यक प्रक्रिया अधिकृत संकेतस्थळावर तपासा. कोणत्याही सहाय्याची किंवा मान्यतेची हमी दिली जात नाही.', 'Startup recognition and support have separate eligibility conditions. Check which criteria and application steps apply to your business on the official website. No support or recognition is guaranteed by this listing.', '[{"label":"Startup India · Government of India","url":"https://www.startupindia.gov.in/"}]'::jsonb, 'EVERGREEN', 'PUBLISHED', true, false, 'https://www.startupindia.gov.in/', '2026-10-17T18:30:00Z'::timestamp, CURRENT_TIMESTAMP) ON CONFLICT ("slug") DO NOTHING;
INSERT INTO "SiteSettings" ("id","heroTitleMr","heroTitleEn","heroDescriptionMr","heroDescriptionEn","updatedAt") VALUES ('public', 'आपला वारसा.
आपली माणसं. आपली प्रगती.', 'Rooted in heritage.
Connected for tomorrow.', 'आगरी समाजाची संस्कृती जाणून घ्या, आपल्या परिसरातील उद्योजकांशी जोडा आणि शिक्षण व करिअरच्या नव्या वाटा शोधा.', 'Discover Aagri heritage, connect with local entrepreneurs, and find trusted resources for learning, work and a shared future.', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
